pub fn path_suffix(path: &Path, detail: usize) -> String {
    let mut components: Vec<_> = path
        .components()
        .rev()
        .filter_map(|component| match component {
            std::path::Component::Normal(s) => Some(s.to_string_lossy()),
            _ => None,
        })
        .take(detail + 1)
        .collect();
    components.reverse();
    components.join("/")
}

